ole.log(res.data)\r\n\t\tawait client.get(\"/gateway/Pets/\").then((response) => {\r\n\t\t\tpets = response;\r\n\t\t\tconsole.log(\"pets =>\", pets);\r\n\t\t});\r\n\t\tawait client.get(\"/gateway/Genderes/\").then((response) => {\r\n\t\t\tgenderes = response;\r\n\t\t\tconsole.log(\"genderes =>\", genderes);\r\n\t\t});\r\n\t\tawait client.get(\"/gateway/PetTypes/\").then((response) => {\r\n\t\t\tpetTypes = response;\r\n\t\t\tconsole.log(\"petTypes =>\", petTypes);\r\n\t\t});\r\n\t\tawait client.get(\"/gateway/Breeds/\").then((response) => {\r\n\t\t\tbreeds = response;\r\n\t\t\tconsole.log(\"breeds => \", breeds);\r\n\t\t});\r\n\t};\r\n\r\n\tinitialLoad();\r\n\r\n\tlet pet = {\r\n\t\tid: \"\",\r\n\t\tclientUniqueId: \"\",\r\n\t\tcompanyId: \"\",\r\n\t\tname: \"\",\r\n\t\tpetTypeId: \"\",\r\n\t\tbreedId: \"\",\r\n\t\tgenderId: \"\",\r\n\t\tage: \"\",\r\n\t\tcolor: \"\",\r\n\t};\r\n\r\n\tlet editStatus = false;\r\n\r\n\tconst cleanPet = () => {\r\n\t\tpet = {};\r\n\t};\r\n\tlet showForm = false;\r\n\tconst openNew = (open) => {\r\n\t\tshowForm = open;\r\n\t\tif (!open && editStatus) {\r\n\t\t\teditStatus = false;\r\n\t\t\tcleanPet();\r\n\t\t}\r\n\t};\r\n\r\n\tconst addPet = async () => {\r\n\t\tif (!clientSelected.numeroIdentificacion) {\r\n\t\t\ttoast({ type: \"warning\", message: \"Debe asignar un cliente\" });\r\n\t\t\treturn;\r\n\t\t}\r\n\t\tif (!pet.petTypeId) {\r\n\t\t\ttoast({ type: \"warning\", message: \"Debe seleccionar una especie\" });\r\n\t\t\treturn;\r\n\t\t}\r\n\t\tif (!pet.genderId) {\r\n\t\t\ttoast({ type: \"warning\", message: \"Debe seleccionar el sexo\" });\r\n\t\t\treturn;\r\n\t\t}\r\n\t\tconst newPet = {\r\n\t\t\tclientUniqueId: clientSelected.numeroIdentificacion,\r\n\t\t\tcompanyId: clientSelected.rucEmpresa,\r\n\t\t\tname: pet.name,\r\n\t\t\tpetTypeId: pet.petTypeId,\r\n\t\t\tbreedId: pet.breedId,\r\n\t\t\tgenderId: pet.genderId,\r\n\t\t\tage: pet.age,\r\n\t\t\tcolor: pet.color,\r\n\t\t};\r\n\t\tawait client\r\n\t\t\t.post(\"/gateway/Pets/\", newPet)\r\n\t\t\t.then((response) => {\r\n\t\t\t\tconsole.log(response);\r\n\t\t\t\ttoast({\r\n\t\t\t\t\ttype: \"success\",\r\n\t\t\t\t\tmessage: \"Registrada exitosamente\",\r\n\t\t\t\t});\r\n\t\t\t\topenNew(false);\r\n\t\t\t\tinitialLoad();\r\n\t\t\t})\r\n\t\t\t.catch((error) => {\r\n\t\t\t\tconsole.log(error);\r\n\t\t\t});\r\n\t\tcleanPet();\r\n\t};\r\n\r\n\tconst deletePet = async (id) => {\r\n\t\tlet { isConfirmed } = await Swal.fire({\r\n\t\t\ttext: \"Esta seguro de eliminar esta mascota\",\r\n\t\t\ticon: \"warning\",\r\n\t\t\tshowCancelButton: true,\r\n\t\t\tconfirmButtonColor: \"#3085d6\",\r\n\t\t\tcancelButtonColor: \"#d33\",\r\n\t\t\tconfirmButtonText: \"Si, proceder!\",\r\n\t\t\tcancelButtonText: \"No, cancelar\",\r\n\t\t});\r\n\t\tif (isConfirmed) {\r\n\t\t\tawait client\r\n\t\t\t\t.delete(\"/gateway/Pets/\" + id)\r\n\t\t\t\t.then((response) => {\r\n\t\t\t\t\tconsole.log(response);\r\n\t\t\t\t\ttoast({\r\n\t\t\t\t\t\ttype: \"success\",\r\n\t\t\t\t\t\tmessage: \"Eliminada exitosamente\",\r\n\t\t\t\t\t});\r\n\t\t\t\t\tpets = pets.filter((pet) => pet.id !== id);\r\n\t\t\t\t})\r\n\t\t\t\t.catch((error) => {\r\n\t\t\t\t\tconsole.log(error);\r\n\t\t\t\t});\r\n\t\t}\r\n\t};\r\n\r\n\tconst editPet = (petEdited) => {\r\n\t\teditStatus = true;\r\n\t\tpet = petEdited;\r\n\t};\r\n\r\n\tconst updatePet = async () => {\r\n\t\tlet updatedpet = {\r\n\t\t\tid: pet.id,\r\n\t\t\tclientUniqueId: pet.clientUniqueId,\r\n\t\t\tcompanyId: pet.companyId,\r\n\t\t\tname: pet.name,\r\n\t\t\tpetType: pet.petType,\r\n\t\t\tpetTypeId: pet.petTypeId,\r\n\t\t\tbreed: pet.breed,\r\n\t\t\tbreedId: pet.breedId,\r\n\t\t\tgender: pet.gender,\r\n\t\t\tgenderId: pet.genderId,\r\n\t\t\tage: pet.age,\r\n\t\t\tcolor: pet.color,\r\n\t\t\tenabled: pet.enabled,\r\n\t\t};\r\n\r\n\t\tawait client\r\n\t\t\t.put(\"/gateway/Pets/\" + updatedpet.id, updatedpet)\r\n\t\t\t.then((response) => {\r\n\t\t\t\tconst petIndex = pets.findIndex((p) => p.id === pet.id);\r\n\t\t\t\tpets[petIndex] = updatedpet;\r\n\t\t\t\tconsole.log(response);\r\n\t\t\t\ttoast({\r\n\t\t\t\t\ttype: \"success\",\r\n\t\t\t\t\tmessage: \"Actualizada exitosamente\",\r\n\t\t\t\t});\r\n\t\t\t\topenNew(false);\r\n\t\t\t\tinitialLoad();\r\n\t\t\t})\r\n\t\t\t.catch((error) => {\r\n\t\t\t\tconsole.log(error);\r\n\t\t\t});\r\n\r\n\t\tcleanPet();\r\n\t\teditStatus = false;\r\n\t};\r\n\r\n\tconst onSubmitHandler = () => {\r\n\t\tif (!editStatus) {\r\n\t\t\taddPet();\r\n\t\t} else {\r\n\t\t\tupdatePet();\r\n\t\t}\r\n\t};\r\n\r\n\tfunction disablePet(item) {\r\n\t\tpet = item;\r\n\t\t//console.log(pet)\r\n\t\tupdatePet();\r\n\t}\r\n\r\n\tlet value = \"\";\r\n\tlet isFocused = false;\r\n\t//const onInput = (e) => (value = e.target.value)\r\n\tlet clients = [];\r\n\tconst onInput = async (e) => {\r\n\t\tvalue = e.target.value;\r\n\t\tconsole.log(value);\r\n\t\tif (value.length >= 3) {\r\n\t\t\tlet data = {\r\n\t\t\t\ttextSearch: value,\r\n\t\t\t};\r\n\t\t\tawait client\r\n\t\t\t\t.get(`/gateway/Cliente/Search/`, {\r\n\t\t\t\t\tparams: {\r\n\t\t\t\t\t\tjson: JSON.stringify(data),\r\n\t\t\t\t\t},\r\n\t\t\t\t})\r\n\t\t\t\t.then((response) => {\r\n\t\t\t\t\tif (response.code == \"1\") {\r\n\t\t\t\t\t\tclients = JSON.parse(response.payload);\r\n\t\t\t\t\t\tconsole.log(clients);\r\n\t\t\t\t\t}\r\n\t\t\t\t});\r\n\t\t}\r\n\t};\r\n\tconst onFocus = () => (isFocused = true);\r\n\tconst onBlur = () => (isFocused = false);\r\n\tlet placeholder = \"Buscar cliente\";\r\n\tlet isClientSelected = false;\r\n\tlet clientSelected = {};\r\n\tconst selectClient = (e) => {\r\n\t\tisClientSelected = true;\r\n\t\tclientSelected = e;\r\n\t\tconsole.log(e);\r\n\t};\r\n\r\n\tlet filteredPets = [];\r\n\r\n\tlet searchTerm = \"\";\r\n\t// resets language menu if search input is used\r\n\r\n\tconst searchPets = () => {\r\n\t\treturn (filteredPets = pets.filter((pet) => {\r\n\t\t\tlet petName = pet.name.toLowerCase();\r\n\t\t\treturn petName.includes(searchTerm.toLowerCase());\r\n\t\t}));\r\n\t};\r\n</script>\r\n\r\n<div class=\"row page-titles\">\r\n\t<div class=\"col-md-5 align-self-center\">\r\n\t\t<h5 class=\"text-themecolor\">Registro de Mascotas</h5>\r\n\t</div>\r\n\t<div class=\"col-md-7 align-self-center text-right\">\r\n\t\t<div class=\"d-flex justify-content-end align-items-center\">\r\n\t\t\t<button\r\n\t\t\t\ttype=\"button\"\r\n\t\t\t\ton:click={() => openNew(true)}\r\n\t\t\t\tclass=\"btn btn-info d-block d-lg-inline-block m-l-15\"\r\n\t\t\t>\r\n\t\t\t\t<i class=\"fa fa-plus-circle\" /> Nuevo\r\n\t\t\t</button>\r\n\t\t</div>\r\n\t</div>\r\n</div>\r\n\r\n<div class=\"card\">\r\n\t<div class=\"card-body\">\r\n\t\t<!-- <iframe sandbox=\"allow-same-origin allow-scripts allow-popups allow-forms\" src=\"http://205.209.99.71:8006/\"\r\n\t\t\t\t\twidth=\"100%\"\r\n\t\t\t\t\theight=\"500\"\r\n\t\t\t\t\tallowfullscreen\r\n\t\t\t\t\tsandbox>\r\n\t\t\t\t<p>\r\n\t\t\t\t\t<a href=\"/en-US/docs/Glossary\">\r\n\t\t\t\t\t\tFallback link for browsers that don't support iframes\r\n\t\t\t\t\t</a>\r\n\t\t\t\t</p>\r\n\t\t\t</iframe>\r\n\t\t<svelte-app id=\"khalid\" name=\"Khalid\"></svelte-app>\r\n\t\t<svelte-app id=\"paul\" name=\"Paul\"></svelte-app>\r\n\t\t<test-counter></test-counter> -->\r\n\r\n\t\t{#if showForm | editStatus}\r\n\t\t\t<h5 class=\"card-title\">\r\n\t\t\t\t{#if !editStatus}Añadir Mascota{:else}Editar Mascota{/if}\r\n\t\t\t</h5>\r\n\t\t\t<form on:submit|preventDefault={onSubmitHandler}>\r\n\t\t\t\t<div class=\"row\">\r\n\t\t\t\t\t<div class=\"col-xl-6 col-lg-6 col-md-6 col-sm-6 col-12\">\r\n\t\t\t\t\t\t<div class=\"form-group\">\r\n\t\t\t\t\t\t\t<div class=\"input-group\">\r\n\t\t\t\t\t\t\t\t<AdvancedSearch\r\n\t\t\t\t\t\t\t\t\ton:input={onInput}\r\n\t\t\t\t\t\t\t\t\ton:focus={onFocus}\r\n\t\t\t\t\t\t\t\t\ton:blur={onBlur}\r\n\t\t\t\t\t\t\t\t\t{value}\r\n\t\t\t\t\t\t\t\t\t{placeholder}\r\n\t\t\t\t\t\t\t\t/>\r\n\t\t\t\t\t\t\t</div>\r\n\t\t\t\t\t\t\t{#if clients.length > 0 && !isClientSelected}\r\n\t\t\t\t\t\t\t\t<div class=\"floating-results list-group\">\r\n\t\t\t\t\t\t\t\t\t{#each clients as item}\r\n\t\t\t\t\t\t\t\t\t\t<a\r\n\t\t\t\t\t\t\t\t\t\t\thref=\"#\"\r\n\t\t\t\t\t\t\t\t\t\t\tclass=\"list-group-item\"\r\n\t\t\t\t\t\t\t\t\t\t\ton:click={selectClient(item)}\r\n\t\t\t\t\t\t\t\t\t\t\t><i class=\"ti-user\" /> - {item.numeroIdentificacion}\r\n\t\t\t\t\t\t\t\t\t\t\t- {item.nombreFiscal}</a\r\n\t\t\t\t\t\t\t\t\t\t>\r\n\t\t\t\t\t\t\t\t\t{/each}\r\n\t\t\t\t\t\t\t\t</div>{/if}\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t</div>\r\n\t\t\t\t</div>\r\n\t\t\t\t{#if isClientSelected}\r\n\t\t\t\t\t<div class=\"row\">\r\n\t\t\t\t\t\t<div class=\"col-xl-6 col-lg-6 col-md-6 col-sm-6 col-12\">\r\n\t\t\t\t\t\t\t<div class=\"form-group\">\r\n\t\t\t\t\t\t\t\t<label for=\"\">Cliente</label>\r\n\t\t\t\t\t\t\t\t<input\r\n\t\t\t\t\t\t\t\t\ttype=\"text\"\r\n\t\t\t\t\t\t\t\t\tclass=\"form-control\"\r\n\t\t\t\t\t\t\t\t\tdisabled\r\n\t\t\t\t\t\t\t\t\tvalue={clientSelected.nombreFiscal}\r\n\t\t\t\t\t\t\t\t/>\r\n\t\t\t\t\t\t\t</div>\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t\t<div class=\"col-xl-3 col-lg-3 col-md-3 col-sm-3 col-6\">\r\n\t\t\t\t\t\t\t<div class=\"form-group\">\r\n\t\t\t\t\t\t\t\t<label for=\"\">Ruc</label>\r\n\t\t\t\t\t\t\t\t<input\r\n\t\t\t\t\t\t\t\t\ttype=\"text\"\r\n\t\t\t\t\t\t\t\t\tclass=\"form-control\"\r\n\t\t\t\t\t\t\t\t\tdisabled\r\n\t\t\t\t\t\t\t\t\tvalue={clientSelected.numeroIdentificacion}\r\n\t\t\t\t\t\t\t\t/>\r\n\t\t\t\t\t\t\t</div>\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t\t<div class=\"col-xl-3 col-lg-3 col-md-3 col-sm-3 col-6\">\r\n\t\t\t\t\t\t\t<div class=\"form-group\">\r\n\t\t\t\t\t\t\t\t<label for=\"\">Email</label>\r\n\t\t\t\t\t\t\t\t<input\r\n\t\t\t\t\t\t\t\t\ttype=\"text\"\r\n\t\t\t\t\t\t\t\t\tclass=\"form-control\"\r\n\t\t\t\t\t\t\t\t\tdisabled\r\n\t\t\t\t\t\t\t\t\tvalue={clientSelected.correo}\r\n\t\t\t\t\t\t\t\t/>\r\n\t\t\t\t\t\t\t</div>\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t</div>\r\n\t\t\t\t{/if}\r\n\t\t\t\t<div class=\"row\">\r\n\t\t\t\t\t<div class=\"col-xl-6 col-lg-6 col-md-6 col-sm-6 col-12\">\r\n\t\t\t\t\t\t<div class=\"form-group\">\r\n\t\t\t\t\t\t\t<label for=\"pet-name\">Nombre</label>\r\n\t\t\t\t\t\t\t<input\r\n\t\t\t\t\t\t\t\tbind:value={pet.name}\r\n\t\t\t\t\t\t\t\ttype=\"text\"\r\n\t\t\t\t\t\t\t\tclass=\"form-control\"\r\n\t\t\t\t\t\t\t\tid=\"pet-name\"\r\n\t\t\t\t\t\t\t\tplaceholder=\"Nombre\"\r\n\t\t\t\t\t\t\t\trequired\r\n\t\t\t\t\t\t\t/>\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t</div>\r\n\t\t\t\t\t<div class=\"col-xl-3 col-lg-3 col-md-3 col-sm-3 col-3\">\r\n\t\t\t\t\t\t<div class=\"form-group\">\r\n\t\t\t\t\t\t\t<label for=\"petType\">Tipo:</label>\r\n\t\t\t\t\t\t\t<select\r\n\t\t\t\t\t\t\t\tname=\"petType\"\r\n\t\t\t\t\t\t\t\tid=\"petType\"\r\n\t\t\t\t\t\t\t\tclass=\"form-control\"\r\n\t\t\t\t\t\t\t\trequired\r\n\t\t\t\t\t\t\t\tbind:value={pet.petTypeId}\r\n\t\t\t\t\t\t\t>\r\n\t\t\t\t\t\t\t\t<option selected disabled\r\n\t\t\t\t\t\t\t\t\t>Seleccione el tipo</option\r\n\t\t\t\t\t\t\t\t>\r\n\t\t\t\t\t\t\t\t{#each petTypes as item}\r\n\t\t\t\t\t\t\t\t\t<option value={item.id}>{item.name}</option>\r\n\t\t\t\t\t\t\t\t{/each}\r\n\t\t\t\t\t\t\t</select>\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t</div>\r\n\r\n\t\t\t\t\t<div class=\"col-xl-3 col-lg-3 col-md-3 col-sm-3 col-6\">\r\n\t\t\t\t\t\t<div class=\"form-group\">\r\n\t\t\t\t\t\t\t<label for=\"breed\">Raza:</label>\r\n\t\t\t\t\t\t\t<select\r\n\t\t\t\t\t\t\t\tname=\"breed\"\r\n\t\t\t\t\t\t\t\tid=\"breed\"\r\n\t\t\t\t\t\t\t\tclass=\"form-control\"\r\n\t\t\t\t\t\t\t\trequired\r\n\t\t\t\t\t\t\t\tbind:value={pet.breedId}\r\n\t\t\t\t\t\t\t>\r\n\t\t\t\t\t\t\t\t<option selected disabled\r\n\t\t\t\t\t\t\t\t\t>Seleccione la raza</option\r\n\t\t\t\t\t\t\t\t>\r\n\t\t\t\t\t\t\t\t{#each breeds as item}\r\n\t\t\t\t\t\t\t\t\t<option value={item.id}>{item.name}</option>\r\n\t\t\t\t\t\t\t\t{/each}\r\n\t\t\t\t\t\t\t</select>\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t</div>\r\n\t\t\t\t</div>\r\n\r\n\t\t\t\t<div class=\"row\">\r\n\t\t\t\t\t<div class=\"col-xl-3 col-lg-3 col-md-3 col-sm-3 col-6\">\r\n\t\t\t\t\t\t<div class=\"form-group\">\r\n\t\t\t\t\t\t\t<label for=\"gender\">Sexo:</label>\r\n\t\t\t\t\t\t\t<select\r\n\t\t\t\t\t\t\t\tname=\"gender\"\r\n\t\t\t\t\t\t\t\tid=\"gender\"\r\n\t\t\t\t\t\t\t\tclass=\"form-control\"\r\n\t\t\t\t\t\t\t\tbind:value={pet.genderId}\r\n\t\t\t\t\t\t\t>\r\n\t\t\t\t\t\t\t\t<option selected disabled\r\n\t\t\t\t\t\t\t\t\t>Seleccione el sexo</option\r\n\t\t\t\t\t\t\t\t>\r\n\t\t\t\t\t\t\t\t{#each genderes as item}\r\n\t\t\t\t\t\t\t\t\t<option value={item.id}>{item.name}</option>\r\n\t\t\t\t\t\t\t\t{/each}\r\n\t\t\t\t\t\t\t</select>\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t</div>\r\n\r\n\t\t\t\t\t<div class=\"col-xl-3 col-lg-3 col-md-3 col-sm-3 col-6\">\r\n\t\t\t\t\t\t<div class=\"form-group\">\r\n\t\t\t\t\t\t\t<label for=\"pet-age\">Edad</label>\r\n\t\t\t\t\t\t\t<input\r\n\t\t\t\t\t\t\t\ttype=\"number\"\r\n\t\t\t\t\t\t\t\tid=\"pet-age\"\r\n\t\t\t\t\t\t\t\tclass=\"form-control\"\r\n\t\t\t\t\t\t\t\tstep=\"any\"\r\n\t\t\t\t\t\t\t\trequired\r\n\t\t\t\t\t\t\t\tbind:value={pet.age}\r\n\t\t\t\t\t\t\t/>\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t</div>\r\n\t\t\t\t\t<div class=\"col-xl-3 col-lg-3 col-md-3 col-sm-3 col-6\">\r\n\t\t\t\t\t\t<div class=\"form-group\">\r\n\t\t\t\t\t\t\t<label for=\"pet-color\">Color</label>\r\n\t\t\t\t\t\t\t<input\r\n\t\t\t\t\t\t\t\ttype=\"text\"\r\n\t\t\t\t\t\t\t\tid=\"pet-color\"\r\n\t\t\t\t\t\t\t\tclass=\"form-control\"\r\n\t\t\t\t\t\t\t\tplaceholder=\"blanco\"\r\n\t\t\t\t\t\t\t\trequired\r\n\t\t\t\t\t\t\t\tbind:value={pet.color}\r\n\t\t\t\t\t\t\t/>\r\n\t\t\t\t\t\t</div>\r\n\t\t\t\t\t</div>\r\n\t\t\t\t</div>\r\n\r\n\t\t\t\t<button type=\"submit\" class=\"btn btn-success\">\r\n\t\t\t\t\t<i class=\"ti-save\" />\r\n\t\t\t\t\t{#if !editStatus} Guardar {:else} Actualizar{/if}\r\n\t\t\t\t</button>\r\n\t\t\t\t{#if showForm | editStatus}\r\n\t\t\t\t\t<button\r\n\t\t\t\t\t\ttype=\"button\"\r\n\t\t\t\t\t\tclass=\"btn btn-warning\"\r\n\t\t\t\t\t\ton:click={() => openNew(false)}\r\n\t\t\t\t\t>\r\n\t\t\t\t\t\t<i class=\"ti-close\" />Cancelar\r\n\t\t\t\t\t</button>\r\n\t\t\t\t{/if}\r\n\t\t\t</form>\r\n\t\t\t<hr />\r\n\t\t{/if}\r\n\r\n\t\t<Sea